      de: ["Der Teeanbau im Iran begann Ende des 19. Jahrhunderts.", "Lahidschan wird die Hauptstadt des iranischen Tees genannt.", "Das milde und feuchte Klima ist ideal für den Teeanbau."],
      hu: ["A teatermelés Iránban a 19. század végén kezdődött.", "Láhidzsánt az iráni tea fővárosának nevezik.", "Az enyhe és nedves éghajlat ideális a teatermesztéshez."],
      ro: ["Cultivarea ceaiului în Iran a început la sfârșitul secolului al XIX-lea.", "Lahijan este numit capitala ceaiului iranian.", "Clima blândă și umedă este ideală pentru cultivarea ceaiului."],
      en: ["Tea cultivation in Iran began in the late 19th century.", "Lahijan is called the capital of Iranian tea.", "The mild and humid climate is ideal for growing tea."],
