      es: "En primavera florecen en esta región innumerables rosas de Damasco, que se cosechan para fabricar el famoso agua de rosas iraní.",
      pt: "Na primavera, florescem nesta região inúmeras rosas de Damasco, que são colhidas para a fabricação da famosa água de rosas iraniana.",
