      hu: ["A tavat eredetileg mezőgazdasági víztározóként használták.", "A pavilon korábban királyi nyári rezidenciaként szolgált.", "Ez a város legnépszerűbb rekreációs helyszíne."],
      ro: ["Lacul a fost folosit inițial ca rezervor de apă pentru agricultură.", "Pavilionul a servit anterior ca reședință regală de vară.", "Este cel mai popular loc de recreere din oraș."],
      en: ["The lake was originally used for agriculture as a water reservoir.", "The pavilion previously served as a royal summer residence.", "It is the city's most popular recreation spot."],
